+
+        validateRate(discount, "discount rate");
+        validateRate(tax, "tax rate");
+
+        const boost::multiprecision::cpp_int priceAndDiscountScale =
+            powerOfTen(price.fractionalDigits + discount.fractionalDigits);
+        const boost::multiprecision::cpp_int discountFactor =
+            powerOfTen(discount.fractionalDigits) - discount.value;
+        const boost::multiprecision::cpp_int shippingCents =
+            shippingMethod == ShippingMethod::Expedited ? 1500 : 0;
+        const boost::multiprecision::cpp_int subtotalInScaledCents =
+            price.value * discountFactor * 100 + shippingCents * priceAndDiscountScale;
+        const boost::multiprecision::cpp_int taxFactor =
+            powerOfTen(tax.fractionalDigits) + tax.value;
+        const boost::multiprecision::cpp_int centsNumerator = subtotalInScaledCents * taxFactor;
+        const boost::multiprecision::cpp_int centsDenominator =
+            priceAndDiscountScale * powerOfTen(tax.fractionalDigits);
+
+        return formatCents(roundHalfEven(centsNumerator, centsDenominator));
+    }
+
+private:
+    struct Decimal
+    {
+        boost::multiprecision::cpp_int value;
+        std::size_t fractionalDigits;
+    };
+
+    static Decimal parseDecimal(const std::string& text, const char* name)
+    {
+        const std::size_t point = text.find('.');
+        const bool hasPoint = point != std::string::npos;
+        const std::size_t integerDigits = hasPoint ? point : text.size();
+        const std::size_t fractionalDigits = hasPoint ? text.size() - point - 1 : 0;
+
+        if (integerDigits == 0 || (hasPoint && fractionalDigits == 0)) {
+            throw std::invalid_argument(std::string(name) + " must be a nonnegative decimal");
+        }
+
+        boost::multiprecision::cpp_int value = 0;
+        for (std::size_t index = 0; index < text.size(); ++index) {
+            const char character = text[index];
+            if (character == '.' && index == point) {
+                continue;
+            }
+            if (character < '0' || character > '9') {
+                throw std::invalid_argument(std::string(name) + " must be a nonnegative decimal");
+            }
+            value = value * 10 + (character - '0');
+        }
+
+        return {value, fractionalDigits};
+    }
+
+    static void validateRate(const Decimal& rate, const char* name)
+    {
+        if (rate.value > powerOfTen(rate.fractionalDigits)) {
+            throw std::invalid_argument(std::string(name) + " must be between 0 and 1");
+        }
+    }
+
+    static boost::multiprecision::cpp_int powerOfTen(std::size_t exponent)
+    {
+        boost::multiprecision::cpp_int result = 1;
+        for (std::size_t index = 0; index < exponent; ++index) {
+            result *= 10;
+        }
+        return result;
+    }
+
+    static boost::multiprecision::cpp_int roundHalfEven(
+        const boost::multiprecision::cpp_int& numerator,
+        const boost::multiprecision::cpp_int& denominator)
+    {
+        boost::multiprecision::cpp_int quotient = numerator / denominator;
+        const boost::multiprecision::cpp_int remainder = numerator % denominator;
+        const boost::multiprecision::cpp_int twiceRemainder = remainder * 2;
+
+        if (twiceRemainder > denominator ||
+            (twiceRemainder == denominator && quotient % 2 != 0)) {
+            ++quotient;
+        }
+        return quotient;
+    }
+
+    static std::string formatCents(const boost::multiprecision::cpp_int& cents)
+    {
+        const boost::multiprecision::cpp_int dollars = cents / 100;
+        const boost::multiprecision::cpp_int remainder = cents % 100;
+        const std::string centsText = remainder.convert_to<std::string>();
+
+        return dollars.convert_to<std::string>() + "." +
+               (centsText.size() == 1 ? "0" : "") + centsText;
+    }
 };
